// Robin has a hidden goodwill score: insults lower it by 1, while apologies and gifts raise it by 1; he is warm only if the final score is positive.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") {
      score -= 1;
    } else {
      score += 1;
    }
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

// Robin counts only apologies and insults; gifts do not affect his final mood, and he is warm exactly when apologies outnumber insults.
function visible(actions) {
  let apologies = 0;
  let insults = 0;
  for (const action of actions) {
    if (action === "apologise") {
      apologies += 1;
    } else if (action === "insult") {
      insults += 1;
    }
  }
  return { mood: apologies > insults ? "warm" : "cold" };
}

// Robin starts cold; an apology can warm him, but any occurrence of two insults in a row makes him stay cold for the whole observation.
function visible(actions) {
  let hasApology = false;
  let consecutiveInsults = false;
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === "apologise") {
      hasApology = true;
    }
    if (i > 0 && actions[i] === "insult" && actions[i - 1] === "insult") {
      consecutiveInsults = true;
    }
  }
  return { mood: hasApology && !consecutiveInsults ? "warm" : "cold" };
}

